WFJ.Data.add("quest", {
  [82060] = { "Chimica clandestina", nil, nil, nil, nil, 0xadf9c333, nil, nil, nil, nil, ".mmmm" },
  [82062] = { "Per sempre", "Parla con il Viandante Temprato.", "Dovevo essere sicuro di potermi fidare di te. Amici di questo tipo sono difficili da trovare.\n\nC'è una malignità che cresce, una fazione sinistra all'interno di Azeroth. Sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ lavorano inconsapevolmente ai propri fini. Rallentare i loro avanzamenti e creare reti di informazioni è tutto ciò per cui abbiamo risorse.\n\nPrendi questo, solleva il morale e ripensa a giorni migliori. Presto arriverà il momento in cui avremo bisogno dei nostri numeri rafforzati per una dimostrazione di forza.", nil, nil, 0x755f5662, 0x4e44c669, 0xe84caf1e, nil, nil, "...mm" },
  [82068] = { "Combattere le Incursioni dell'Incubo", "Completa una missione di Incursione dell'Incubo a Feralas o nelle Entroterre, poi presentati dalla capitana di campo Korlian o dal capitano di campo Arunnel.", "Completa oggi una missione dell'Incursione dell'Incubo a Feralas o nelle Entroterre e otterrai una ricompensa extra.", nil, nil, 0x241d595b, 0x5084f443, 0x9a52a9c3, nil, nil, "...mm" },
  [82081] = { "Un rituale interrotto", "Porta la Scapola dell'Avatar Caduto a Molthor sull'⟦Yojamba Isle=Isola di Yojamba⟧.", "Questa scapola intatta è fin troppo riconoscibile: Hakkar è stato evocato nel mondo fisico e sconfitto. I troll dell'Isola di Yojamba vorranno saperne di più su ciò che è accaduto dentro il Tempio di Atal'Hakkar.", nil, nil, 0xa567ee51, 0x60041f65, 0xefdd0445, nil, nil, "...mm" },
  [82084] = { "Una lezione di alfabetizzazione", "Rintraccia e raccogli i materiali per il libro degli incantesimi richiesti dal bibliotecario.", "I tuoi progressi nelle arti arcane sono stati esemplari, {name}. Credo che tu sia pront<o/a> a scrivere un libro degli incantesimi tutto tuo.\n\nVediamo... una penna dai silvagufi delle Entroterre, e inchiostro ricavato dalla resina di silitide... sì, andrà bene. E per le pagine, il miglior Papiro Farraki!", nil, nil, 0xd7b2b1fa, 0x821a8de0, 0x9a46966a, nil, nil, "...mm" },
  [82135] = { "Il prezzo della speranza", "Porta la Sfera Echeggiante di Mannoroc a ⟦Katherine the Pure=Katherine la Pura⟧ a ⟦Stormwind=Roccavento⟧.", "<Aeonas non dice nulla, ti porge soltanto la sfera e si allontana>", nil, nil, 0x7f9da2aa, 0x7b393e27, 0x31a53d64, nil, nil, "...mm" },
  [82208] = { "Grande amico della biblioteca", nil, nil, nil, nil, 0xf10ee12c, nil, nil, nil, nil, ".mmmm" },
  [82656] = { "⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧", "Porta 2 Pettorale Corazzato di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Gloves=Guanti di Scaglie di Tartaruga⟧ e un Wildvine a ⟦Jangdor Swiftstrider=Jangdor Passo Lesto⟧, all'⟦Camp Mojache=Accampamento Mojache⟧.", "La veste di Cuoio Selvatico è il pezzo fondamentale di ogni completo di Cuoio Selvatico. La struttura della veste e la vite selvaggia intrecciata in essa danno un capo che offre la massima protezione al torso e lascia che la potente magia scorra attraverso l'indumento.\n\nPer questo schema mi serviranno due pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due paia di guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e una vite selvaggia. Non è una lezione facile, ma hai di certo l'abilità per completarla.", nil, nil, 0x762367c6, 0x8af7a605, 0x0f2311f8, nil, nil, "...mm" },
  [82657] = { "⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧", "Porta 2 Pettorale Corazzato di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Gloves=Guanti di Scaglie di Tartaruga⟧ e un Wildvine a Pratt McGrubben, alla Roccaforte di Piumaluna.", "La veste di Cuoio Selvatico è il pezzo fondamentale di ogni completo di Cuoio Selvatico. La struttura della veste si fonde con la vite selvaggia, dando un capo che offre la massima protezione al torso e lascia che la potente magia scorra attraverso l'indumento.\n\nPer questo schema mi serviranno due pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due paia di guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e una vite selvaggia. È una richiesta impegnativa, ma per te non dovrebbe essere difficile soddisfarla.", nil, nil, 0x762367c6, 0xe2688b0f, 0xcfbb37a9, nil, nil, "...mm" },
  [82665] = { "La via del Fabbro d'Armi", "Per diventare Fabbro d'Armi devi realizzare i seguenti oggetti e riportarli a Borgosh: 4 Spadone d'Acciaio Lunare, 4 Ascia Massiva di Ferro, 2 Ascia Pesante di Mithril e 2 Grossa Mazza Nera.", "Un giorno creerò un martello leggendario. Un martello degno di un Capoguerra!\n\nÈ l'opera della mia vita, {name}. La mia passione. Riconosco che hai il potenziale per essere dei nostri, uno di noi: un fabbro d'armi. Sono io a poterti aiutare a far fruttare quel potenziale.\n\nTi basta completare un compito semplice. Semplice per una persona dalle tue eccezionali capacità.", nil, nil, 0x7b932606, 0xf37e0ec1, 0x7ccbe88d, nil, nil, "...mm" },
})
